import{_ as r,o as l,c as o,a2 as s,j as a,a as e,t as n}from"./chunks/framework.DToEn73J.js";const c=JSON.parse('{"title":"Prompt 模板化与版本控制","description":"","frontmatter":{"title":"Prompt 模板化与版本控制","chapter":"6.1","order":1,"summary":"Prompt 与代码同仓管理的取舍、模板化抽象与 A/B 灰度发布工程实践。"},"headers":[],"relativePath":"06-engineering-ops/prompt-management.md","filePath":"06-engineering-ops/prompt-management.md","lastUpdated":1787724133000}'),p={name:"06-engineering-ops/prompt-management.md"};function d(i,t,h,g,m,u){return l(),o("div",null,[t[5]||(t[5]=s('<h1 id="prompt-模板化与版本控制" tabindex="-1">Prompt 模板化与版本控制 <a class="header-anchor" href="#prompt-模板化与版本控制" aria-label="Permalink to &quot;Prompt 模板化与版本控制&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>Prompt 是 Agent 行为的“软代码”：随模型迭代频繁变更，却不像代码那样被编译器约束。本页解决的是“如何把提示词当作可版本化、可灰度、可回滚的产物来管理”。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2>',4)),a("ul",null,[a("li",null,[t[0]||(t[0]=a("strong",null,"模板化",-1)),t[1]||(t[1]=e("：用变量占位（如 ",-1)),a("code",null,n(i.tool_schema),1),t[2]||(t[2]=e("、",-1)),a("code",null,n(i.user_query),1),t[3]||(t[3]=e("）抽离稳定骨架与动态上下文，避免在 Agent Loop 里拼接原始字符串。",-1))]),t[4]||(t[4]=a("li",null,[a("strong",null,"版本控制"),e("：与代码同仓 vs 独立管理对比：")],-1))]),t[6]||(t[6]=s(`<table tabindex="0"><thead><tr><th>维度</th><th>与代码同仓</th><th>独立管理（如 Prompt Registry）</th></tr></thead><tbody><tr><td>回滚</td><td>git revert 即可</td><td>平台 label 切换，免发版</td></tr><tr><td>评审</td><td>PR + code review</td><td>UI 协作 + 评分对比</td></tr><tr><td>运行时热更</td><td>需重新部署</td><td>拉取最新 label，秒级生效</td></tr><tr><td>代价</td><td>Prompt 与逻辑耦合</td><td>引入外部依赖、需鉴权</td></tr></tbody></table><ul><li><strong>A/B 与灰度</strong>：用 label（prod/canary）分流，按 <code>user_id</code> 取模分桶；实验组挂 evaluation，对照成本/质量指标再全量。</li></ul><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 最小实现：模板 + label 路由</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prompt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> registry.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;system_prompt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">label</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;canary&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> is_canary(uid) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;prod&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>不版本化的 Prompt 是线上事故的隐形来源：一次措辞改动可能让 Tool 调用参数格式漂移、触发 Prompt Injection 防护失效，且无法定位“上周还好好的”到底改了哪句。模板化 + 版本化把不可见的提示词变成可 diff、可回滚的一等公民。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>把整段系统提示写死在业务代码里，模型升级时被迫改代码发版。</li><li>灰度只看成功率，忽略成本与延迟——劣质 Prompt 可能更贵。</li></ul><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li><strong>Langfuse Prompt Management</strong>：版本控制 + label 部署 + Playground（<a href="https://langfuse.com/docs/prompts%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://langfuse.com/docs/prompts）。</a></li><li><strong>Anthropic Prompt Caching</strong>：模板复用配合缓存降低重复前缀成本（<a href="https://docs.anthropic.com/en/docs/build-with-claude/prompt-caching%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://docs.anthropic.com/en/docs/build-with-claude/prompt-caching）。</a></li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/fk-ai-agent/06-engineering-ops/observability-otel-langfuse">/06-engineering-ops/observability-otel-langfuse</a></li><li><a href="/fk-ai-agent/06-engineering-ops/cost-latency">/06-engineering-ops/cost-latency</a></li><li><a href="/fk-ai-agent/01-agent-basics/agent-loop">/01-agent-basics/agent-loop</a></li><li><a href="/fk-ai-agent/03-context-memory/context-engineering">/03-context-memory/context-engineering</a></li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>`,13))])}const b=r(p,[["render",d]]);export{c as __pageData,b as default};
